from decimal import Decimal
from typing import Any


def _value(image: dict | None, column: str) -> Any:
    if image is None:
        return ""
    value = image.get(column, "")
    return "" if value is None else value


def _text(image: dict | None, column: str) -> str:
    value = _value(image, column)
    return value if isinstance(value, str) else str(value)


def _number(value: Any) -> Decimal:
    if value is None or value == "":
        return Decimal(0)
    return Decimal(str(value))


def _failure(code: str, message: str, severity: str = "BLOCK") -> dict:
    return {
        "code": code,
        "message": message,
        "severity": severity,
    }


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    today: str = "20260901",
) -> list[dict]:
    del today
    errors: list[dict] = []

    # ACC-001
    if event in ("INSERT", "UPDATE"):
        if len(_text(record, "ACCT_NM")) < 2:
            errors.append(
                _failure("E1001", "Account name too short")
            )

    # ACC-002
    if event in ("INSERT", "UPDATE"):
        if _text(record, "ACCT_TYP") not in ("C", "P", "R", "X"):
            errors.append(
                _failure("E1002", "Invalid account type")
            )

    # ACC-003
    if event in ("INSERT", "UPDATE"):
        annual_revenue = _number(_value(record, "ANN_REV"))
        if annual_revenue < 0:
            errors.append(
                _failure("E1003", "Annual revenue negative")
            )

    # ACC-004
    if event == "UPDATE":
        release_with_nonpositive_limit = (
            _text(old, "CRED_HOLD") == "Y"
            and _text(record, "CRED_HOLD") == "N"
            and _number(_value(record, "CRED_LIMIT")) <= 0
        )
        if release_with_nonpositive_limit:
            errors.append(
                _failure(
                    "E1004",
                    "Cannot release credit hold with zero credit limit",
                )
            )

    # ACC-005
    if event in ("INSERT", "UPDATE"):
        if len(_text(record, "REGION_CD")) != 3:
            errors.append(
                _failure(
                    "E1005",
                    "Region code must be 3 chars",
                    "WARN",
                )
            )

    return errors


def is_blocked(errors: list[dict]) -> bool:
    return any(error.get("severity") == "BLOCK" for error in errors)
